public class DecisionDemo {
    private static final Logger log = Logger.getLogger("Decision");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Two real options for the fund-transfer design.
        List<DecisionOption> options = List.of(
            new DecisionOption("Sync strongly-consistent",
                9, 5, 6, "Simpler + correct, but one DB outage blocks all transfers"),
            new DecisionOption("Async eventually-consistent",
                7, 9, 7, "Decoupled + fast, but needs reconciliation for stuck transfers"));

        DecisionEngine engine = new DecisionEngine(log);
        engine.decide(options);
    }
}
