package com.bank.decision.model;

// A candidate design scored on correctness, latency, and cost (1-10), plus its trade-off.
public class DecisionOption {
    private final String name;
    private final int correctness;   // higher is better
    private final int latency;       // higher = faster/better here
    private final int cost;          // higher = cheaper/better here
    private final String tradeOff;   // the honest downside

    public DecisionOption(String name, int correctness, int latency, int cost, String tradeOff) {
        this.name = name;
        this.correctness = correctness;
        this.latency = latency;
        this.cost = cost;
        this.tradeOff = tradeOff;
    }

    public String getName() { return name; }
    public int getCorrectness() { return correctness; }
    public int getLatency() { return latency; }
    public int getCost() { return cost; }
    public String getTradeOff() { return tradeOff; }
}
