package com.bank.decision.service;

import com.bank.decision.model.DecisionOption;
import java.util.Comparator;
import java.util.List;
import java.util.logging.*;

// Scores options with weighted criteria, picks the winner, and reports the trade-off.
public class DecisionEngine {
    private final Logger log;

    // Correctness matters most in a money system — weight it heaviest.
    private static final double W_CORRECTNESS = 0.5;
    private static final double W_LATENCY = 0.3;
    private static final double W_COST = 0.2;

    public DecisionEngine(Logger log) { this.log = log; }

    public DecisionOption decide(List<DecisionOption> options) {
        options.forEach(o -> log.info(() ->
            "Option " + o.getName() + " score=" + score(o)));

        DecisionOption winner = options.stream()
            .max(Comparator.comparingDouble(this::score))
            .orElseThrow();

        log.info(() -> "DECISION: " + winner.getName()
            + " (score=" + score(winner) + ")");
        // Always acknowledge the downside of the chosen option.
        log.warning(() -> "TRADE-OFF accepted: " + winner.getTradeOff());
        return winner;
    }

    private double score(DecisionOption o) {
        return W_CORRECTNESS * o.getCorrectness()
             + W_LATENCY * o.getLatency()
             + W_COST * o.getCost();
    }
}
